def _cell(lines, de=False):
    cls = ' class="de"' if de else ""
    return f"<td{cls}>" + "".join(f"<div>{l}</div>" for l in lines) + "</td>"

def table():
    h = ['<div class="pg-tablewrap"><table class="pg-copy"><colgroup><col style="width:10%"><col style="width:10%"><col style="width:8%"><col style="width:6.5%"><col style="width:13%"><col style="width:18.5%"><col style="width:13%"><col style="width:21%"></colgroup>',
         "<thead><tr><th>State</th><th>Timing / trigger</th><th>Colour</th><th>Symbol</th><th>Headline (EN)</th><th>Sub-lines (EN)</th><th>Headline (DE)</th><th>Sub-lines (DE)</th></tr></thead><tbody>"]
    for r in ROWS:
        if r[0] == G:
            h.append(f'<tr class="grp"><td colspan="8">{r[1]}</td></tr>')
            continue
        st, tm, col, sym, eh, es, dh, ds = r
        c = f'<span class="dot" style="background:{col[0]}"></span>{col[1]}' if isinstance(col, tuple) else col
        h.append(f'<tr><td>{st}</td><td class="t">{tm}</td><td>{c}</td><td>{sym}</td><td>{eh}</td>{_cell(es)}<td class="de">{dh}</td>{_cell(ds, True)}</tr>')
    h.append("</tbody></table></div>")
    return "".join(h)

TABLE = table()
